import{_ as o,l,o as e,c as s,v as t,p as h,x as r,d as n,i as m,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"反射率与镜数预算","description":"","frontmatter":{"title":"反射率与镜数预算","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/reflectivity-mirror-count.md","filePath":"litho/reflectivity-mirror-count.md","lastUpdated":1789023840000}'),p={name:"litho/reflectivity-mirror-count.md"};function c(A,a,_,u,f,E){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="反射率与镜数预算" tabindex="-1">反射率与镜数预算 <a class="header-anchor" href="#反射率与镜数预算" aria-label="Permalink to &quot;反射率与镜数预算&quot;">​</a></h1><div class="epigraph"><p>单面约 70% 看起来体面；六面一乘只剩约一成。镜数是光源功率的放大器，也是 High-NA 光学布局的第一约束。</p><footer>—— 据 ASML / Zeiss 对 EUV 多层反射率与投影镜张数；Bakshi 系统透过率</footer></div><p><a href="/litho/msfr">上一课</a>把中频粗糙从面形里拆出。缺口是能量账：无论 PSD 多干净，每一面仍只有约 70% 的峰值 \\(R\\)，其余被吸收或散射。张数 \\(N\\) 把透过率写成 \\(R^N\\)，直接倒逼 <a href="/litho/euv-power-roadmap">IF 功率路线</a>。光如何被切成扫描用的弧形狭缝，留给<a href="/litho/ring-field">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/euv-multilayer-mirror">多层膜</a>课已经给出单面布拉格反射。进阶课序补的是预算乘法。NXE 一类 0.33 NA 投影公开为六面反射镜量级；再加上收集、照明、掩模（双程还要过 pellicle），硅片上只剩很小一份带内功率。\\(R\\) 从 0.70 掉到 0.65，六镜透过率从约 0.12 掉到约 0.075，产能或激光墙插立刻见血。</p><p>缺口是把 \\(N\\) 当成设计变量，而不是抱怨「EUV 镜子不够亮」。加镜可以校正像差、抬 NA、做变形光学；每加一面就乘一次 \\(R\\)，并加一份吸收热与一份 MSFR。High-NA 的光学布局必须在「像差自由度」和「光子」之间取点，半场、变形倍率都是这张账的解，不是单独的市场名词。</p> \\[T_{\\mathrm{POB}} \\sim R^{N},\\qquad P_{\\mathrm{wafer}} \\sim P_{\\mathrm{IF}}\\cdot T_{\\mathrm{ill}}\\cdot R_{\\mathrm{mask}}\\cdot T_{\\mathrm{pell}}^2\\cdot T_{\\mathrm{POB}}. \\]<p><span class="marginnote">70% 是近正入射峰值量级，随角度和偏振掉。大 NA 下 s/p 分叉，有效 \\(R\\) 低于小样品的法向测量。不要用实验室单镜纪录当六镜系统透过率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算表逐面列：设计角、周期、带宽重叠、偏振、污染余量。收集镜 \\(R_{\\mathrm{col}}(t)\\) 单独成列，因为寿命斜率最大。照明镜组张数随光瞳整形变，FlexPupil 一类可编程照明用的反射面同样进乘法。掩模多层是「镜子 + 图形」，吸收体区域不反射，开孔率进平均功率。</p><p>工程判据：在目标 NA 与场尺寸下，选最小 \\(N\\) 使波前可收。\\(N\\) 减不下来，就减场（环形场、半场）或上变形，把掩模侧角度压回多层能维持高 \\(R\\) 的窗。<a href="/litho/anamorphic-projection">变形光学</a> 是镜数–角度–场的联合解。</p><h3 id="带宽重叠随角走-有效-再打折" tabindex="-1">带宽重叠随角走，有效 \\(R\\) 再打折 <a class="header-anchor" href="#带宽重叠随角走-有效-再打折" aria-label="Permalink to &quot;带宽重叠随角走，有效 $R$ 再打折&quot;">​</a></h3><p>每一面的布拉格通带必须与锡 UTA 和上游镜子的角谱重叠。大 NA 下入射角范围变宽，重叠面积缩小，峰值 \\(R\\) 量到了也进不了系统。预算表要写有效带内 \\(R(\\theta)\\)，不能写样品法向峰值。这是环形场限制瞬时视场的能量理由之一。</p>',13)),(e(),h(d,null,{default:r(()=>[m(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%8D%95%E9%9D%A2%20R%20%E7%BA%A6%200.70%22%5D%20--%3E%20POW%5B%22R%20%E7%9A%84%20N%20%E6%AC%A1%E6%96%B9%22%5D%0A%20%20N%5B%22%E6%8A%95%E5%BD%B1%E9%95%9C%E5%BC%A0%E6%95%B0%22%5D%20--%3E%20POW%0A%20%20POW%20--%3E%20IF%5B%22%E5%80%92%E9%80%BC%20IF%20%E5%8A%9F%E7%8E%87%22%5D%0A%20%20ANG%5B%22%E5%A4%A7%E8%A7%92%E5%BA%A6%E6%8E%89%20R%22%5D%20--%3E%20POW%0A%20%20POL%5B%22s%2Fp%20%E5%88%86%E5%8F%89%22%5D%20--%3E%20POW%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每面吸收的 \\((1-R)\\) 变成热。\\(N\\) 越大，总吸收越大，面形热漂越难管。同时每面贡献一份 TIS/MSFR，对比底座随 \\(N\\) 涨。所以「多加两面把像差做漂亮」会在光子和 flare 上同时罚款。锡 UTA 与多层 2% 通带必须在每一面的角谱下仍重叠；角一宽，有效 \\(R\\) 掉，等效于 \\(N\\) 又加了一面。</p><p><span class="marginnote">吸收热在真空里只能靠传导和辐射。镜数预算也是热预算。功率路线往 1 kW 走时，照明与投影的吸收瓦数一起涨。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲环形场为什么是弧，下一课才讲场几何。不重写 Mo/Si 周期公式。出处：ASML/Zeiss 反射率与镜数；Bakshi 能量流；多层膜课的 0.70⁶ 数量级账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>系统透过率按 \\(R^N\\) 掉；镜数是 IF 功率和 High-NA 布局的硬约束。</li><li>有效 \\(R\\) 随入射角和偏振变，峰值样品数不能代入整机。</li><li>下一课：在这张能量账下，扫描场为什么做成环形。</li><li>出处：ASML、Zeiss、Bakshi；<a href="/litho/euv-multilayer-mirror">多层膜</a>。</li></ul>',7))])}const R=o(p,[["render",c]]);export{P as __pageData,R as default};
